package main

import (
	"fmt"
	"os"
)

// loadConfig reads credentials from the environment; they are never hard-coded.
func loadConfig() (Config, error) {
	key := os.Getenv("API_KEY")
	if key == "" {
		return Config{}, fmt.Errorf("API_KEY is not set")
	}
	password := os.Getenv("DB_PASSWORD")
	token := os.Getenv("GITHUB_TOKEN")
	return Config{APIKey: key, Password: password, Token: token}, nil
}
